function [m] = bdot(b1, b2, dt, bn, k, m_max)
%BDOT  B-dot on two successive field directions dt apart, gain k over the field strength bn.
%   b1: real[1][3] (passed a plain number)
%   b2: real[1][3] (passed a plain number)
%   dt: real[1] (passed a plain number)
%   bn: real[1] (passed a plain number)
%   k: real[1] (passed a plain number)
%   m_max: real[1] (passed a plain number)
%   returns m: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    m = zeros(3, 1);
    u1 = asils.pc.unit_(b1);
    u2 = asils.pc.unit_(b2);
    r = zeros(3, 1);
    for i = (0):((3) - 1)
        r((i) + 1) = (((-((k / bn))) * (u2((i) + 1) - u1((i) + 1))) / dt);
    end
    m = asils.alg.control.sat_dipole(r, m_max);
end
